const props=defineProps<{findings:Finding[];storageReady:boolean;storageError:string;viewerReady:boolean;scenarioActive:boolean}>()
defineEmits<{navigate:[destination:WorkspaceDestination];open:[id:string];locate:[assetId:string];reload:[];demo:[]}>()
const summary=computed(()=>aircraftDashboard(props.findings))
const metric=(value:number)=>props.storageReady?value:'—'
</script>
