    <section class="dashboard-section"><header><div><h3><PhCalendarCheck :size="18" /> Maintenance berikutnya</h3><p>Aturan simulasi pada snapshot demo.</p></div><button class="text-button dashboard-maintenance-link" @click="$emit('navigate',{tab:'maintenance',maintenance:'attention'})">{{ summary.due }} jatuh tempo · {{ summary.soon }} segera<PhArrowRight :size="15" /></button></header><button v-for="plan in summary.plans" :key="plan.id" class="dashboard-plan" @click="$emit('navigate',{tab:'maintenance',maintenance:plan.due.status})"><span>{{ plan.title }}</span><span class="operation-status" :class="plan.due.status">{{ maintenanceStatusLabels[plan.due.status] }}</span></button></section>
   </div>
  </div>
  <div class="dashboard-bottom"><section class="dashboard-section"><header><div><h3>Aktivitas terakhir</h3><p>Riwayat tersimpan pada mode yang aktif.</p></div></header><p v-if="storageReady&&!summary.recent.length" class="dashboard-history-empty">Belum ada aktivitas tersimpan.</p><button v-for="{finding,event} in storageReady?summary.recent:[]" :key="finding.id+event.id" class="dashboard-event" @click="$emit('open',finding.id)"><span><strong>{{ findingEventTitle(event) }}</strong><small>{{ finding.title }} · {{ event.actor }}</small></span><time :datetime="event.at">{{ formatDate(event.at) }}</time><PhArrowRight :size="16" /></button></section><section class="dashboard-section dashboard-utilization"><header><div><h3><PhPath :size="18" /> Utilisasi pesawat</h3><p>Akumulasi delapan penerbangan contoh.</p></div></header><strong>{{ formatNumber(flightTotals.distanceKm) }} <small>km</small></strong><p>{{ formatMinutes(flightTotals.minutes) }} terbang · {{ flightTotals.cycles }} siklus</p><button class="button subtle" @click="$emit('navigate',{tab:'flights'})">Lihat catatan penerbangan<PhArrowRight :size="17" /></button></section></div>
 </section>
